class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = Integer.MAX_VALUE;
        int maxProfit = 0;

        for (int price : prices) {
            if (price < minPrice) {
                minPrice = price;
            } else {
                maxProfit = Math.max(maxProfit, price - minPrice);
            }
        }

        return maxProfit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        if (n < 2) {
            return 0;
        }

        int[] maxFuture = new int[n];
        maxFuture[n - 1] = prices[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            maxFuture[i] = Math.max(prices[i], maxFuture[i + 1]);
        }

        int best = 0;
        for (int buy = 0; buy < n - 1; buy++) {
            best = Math.max(best, maxFuture[buy + 1] - prices[buy]);
        }
        return best;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int maxProfit = 0;
        int currentProfit = 0;

        for (int i = 1; i < prices.length; i++) {
            int dailyGain = prices[i] - prices[i - 1];
            currentProfit = Math.max(0, currentProfit + dailyGain);
            maxProfit = Math.max(maxProfit, currentProfit);
        }

        return maxProfit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int best = 0;
        for (int buy = 0; buy < prices.length; buy++) {
            for (int sell = buy + 1; sell < prices.length; sell++) {
                int profit = prices[sell] - prices[buy];
                best = Math.max(best, profit);
            }
        }
        return best;
    }
}
